const input = $json.body ? $json : { body: $json, headers: {} };
const body = input.body || {};
const headers = input.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const token = String(auth).replace(/^Bearer\s+/i, '');
const mcpUrl = body.mcpUrl || $env.RUNNING_API_MCP_URL || '';
if (!token) throw new Error('Falta Authorization: Bearer <jwt> en el webhook');
if (!body.requestId || !body.activityId) throw new Error('Faltan requestId o activityId en el body');
if (!mcpUrl) throw new Error('Falta mcpUrl en el body o RUNNING_API_MCP_URL');
const separator = mcpUrl.includes('?') ? '&' : '?';
const mcpEndpoint = mcpUrl + separator + 'access_token=' + encodeURIComponent(token);
return [{ json: { token, mcpUrl, mcpEndpoint, requestId: body.requestId, activityId: body.activityId, replace: body.replace === true || body.replace === 'true' } }];

const raw = typeof $json.output === 'string' ? $json.output : JSON.stringify($json.output ?? '');
let text = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start >= 0 && end > start) text = text.slice(start, end + 1);
if (!text) throw new Error('El agente no devolvió un análisis JSON');
const analysis = JSON.parse(text);
const p = $('Preparar llamadas MCP').item.json;
return [{ json: { ...p, analysis, analysisJson: JSON.stringify(analysis) } }];

const raw = $json?.result?.content?.[0]?.text;
let result = {};
try { result = raw ? JSON.parse(raw) : {}; } catch (e) { result = { ok: false, message: 'Respuesta MCP no es JSON: ' + raw }; }
const p = $('Preparar llamadas MCP').item.json;
return [{ json: { ...p, saveResult: result, saved: result.ok === true, analysis: result.analysis || null, failError: result.ok === true ? null : (result.message || JSON.stringify(result)) } }];

const a = $json.analysis;
if (!a) throw new Error('No hay análisis guardado para el mensaje');
const lines = ['🏃 Análisis de la actividad ' + $json.activityId];
if (a.summary) lines.push('', a.summary);
if (Array.isArray(a.strengths) && a.strengths.length) lines.push('', '✅ Puntos fuertes:', ...a.strengths.map(s => '• ' + s));
if (Array.isArray(a.weaknesses) && a.weaknesses.length) lines.push('', '⚠️ Áreas de mejora:', ...a.weaknesses.map(s => '• ' + s));
if (Array.isArray(a.recommendations) && a.recommendations.length) lines.push('', '💡 Recomendaciones:', ...a.recommendations.map(s => '• ' + s));
return [{ json: { telegramText: lines.join('\n') } }];

const p = $('Preparar llamadas MCP').item.json;
const error = $json.failError || $json.saveResult?.message || $json.error?.message || $json.message || 'Error analizando la actividad';
return [{ json: { ...p, failError: String(error) } }];

const p = $('Preparar fallo').item.json;
const text = '⚠️ No se pudo analizar la actividad (' + p.activityId + ').\n' + p.failError + '\nrequestId: ' + p.requestId;
return [{ json: { telegramText: text } }];
